function rewrite(deps: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, range] of Object.entries(deps)) {
    if (!range.startsWith("workspace:")) out[name] = range;
    else if (range === "workspace:*") out[name] = versions[name]!;
    else out[name] = range.slice("workspace:".length) + versions[name];
  }
  return out;
}

