function buildLevels(deps: Map<string, string[]>): string[][] {
  const levels: string[][] = [];
  const done = new Set<string>();
  while (done.size < deps.size) {
    const ready = [...deps.keys()].filter((p) => !done.has(p) && deps.get(p)!.every((d) => done.has(d)));
    if (ready.length === 0) throw new Error("cycle");
    levels.push(ready);
    ready.forEach((p) => done.add(p));
  }
  return levels;
}

