function tierViolations(tiers: Record<string, number>, deps: Record<string, string[]>): string[] {
  const problems: string[] = [];
  for (const [name, needs] of Object.entries(deps)) {
    const own = tiers[name];
    if (own === undefined) {
      problems.push(`${name} has no tier`);
      continue;
    }
    for (const dep of needs) {
      const theirs = tiers[dep];
      if (theirs !== undefined && theirs > own) problems.push(`${name} (tier ${own}) must not depend on ${dep} (tier ${theirs})`);
    }
  }
  return problems;
}

const tiers = { core: 0, logger: 0, auth: 1, database: 1, http: 2 };
const deps = { auth: ["core", "http"], database: ["core"], http: ["auth"], reports: ["http"] };
const problems = tierViolations(tiers, deps);
console.log(problems.length ? problems.join("\n") : "ok");

