function compareReferences(dependencies: string[], references: { path: string }[]) {
  const referenced = references.map((ref) => `@shop/${ref.path.split("/").at(-1)}`);
  return {
    missing: dependencies.filter((dep) => !referenced.includes(dep)),
    extra: referenced.filter((ref) => !dependencies.includes(ref)),
  };
}

