function packagesFor(files: string[]): string[] {
  const names = new Set<string>();
  for (const file of files) {
    const match = /^packages\/([^/]+)\//.exec(file);
    if (match) names.add(`@shop/${match[1]}`);
  }
  return [...names].sort();
}

